tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlaln2, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 17', function test( t ) {
	t.strictEqual( dlaln2.length, 17, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var out;
	var A;
	var B;
	var X;
	var i;

	A = new Float64Array( [ 5.0, 1.0, 1.0, 2.0 ] );
	B = new Float64Array( [ 1.0, 2.0 ] );
	X = new Float64Array( 2 );
	out = new Float64Array( 2 );

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlaln2( value, 'no-transpose', 2, 1, 1.0e-3, 1.0, A, 2, 1.0, 1.0, B, 1, 0.5, 0.0, X, 1, out );
		};
	}
});

