tape( 'the function solves a real 1x1 system (column-major)', function test( t ) {
	var expectedOut;
	var expectedX;
	var data;
	var info;
	var out;
	var A;
	var B;
	var X;

	data = NA1_NW1_COL_MAJOR;

	A = new Float64Array( data.A );
	B = new Float64Array( data.B );
	X = new Float64Array( data.X );
	out = new Float64Array( data.out );

	info = dlaln2( data.order, data.trans, data.NA, data.NW, data.smin, data.ca, A, data.LDA, data.d1, data.d2, B, data.LDB, data.wr, data.wi, X, data.LDX, out );
	expectedX = new Float64Array( data.X_out );
	expectedOut = new Float64Array( data.out_out );

	t.strictEqual( info, data.info, 'returns expected value' );
	t.deepEqual( X, expectedX, 'returns expected value' );
	t.deepEqual( out, expectedOut, 'returns expected value' );
	t.end();
});

